"""Writes docs/REPORT_FACTS.md from the measured JSON files. Run from 8.ProjectCode:  python -m scripts.docs.make_report_facts"""
import glob
import json
import os

import numpy as np

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
EXP = os.path.join(ROOT, "experiments")


def J(*p):
    return json.load(open(os.path.join(EXP, *p), encoding="utf-8"))


def loc(pattern):
    n = 0
    for f in glob.glob(os.path.join(ROOT, pattern), recursive=True):
        if os.path.isfile(f) and "node_modules" not in f and "__pycache__" not in f:
            n += sum(1 for _ in open(f, encoding="utf-8", errors="ignore"))
    return n


SUM, FWD, RR = J("shipped_summary", "metrics.json"), J("forward_test_shipped", "metrics.json"), J("rerun", "metrics.json")
MIL, API = J("mil_study", "metrics.json"), J("api_latency", "metrics.json")
SHIP = json.load(open(os.path.join(ROOT, "artifacts", "metrics.json")))
T = list(SUM["last_close"])
SEEDS = RR["seeds"]
TIERS = ["lstm", "lstm_attention", "lstm_attention_sentiment", "attention_shuffled_sentiment", "hybrid_federated"]
TNAME = {"lstm": "LSTM", "lstm_attention": "LSTM + attention", "lstm_attention_sentiment": "LSTM + attention + sentiment (synthetic headlines)",
         "attention_shuffled_sentiment": "Placebo: attention + time-shuffled sentiment", "hybrid_federated": "Hybrid (FedAvg of the sentiment tier)"}
L = []
w = L.append


def seedwise(tier, key):
    """mean over tickers for each seed -> (mean, std over seeds)"""
    per = [np.mean([RR["tickers"][t]["models"][tier][s][key] for t in T]) for s in range(len(SEEDS))]
    return float(np.mean(per)), float(np.std(per))


def fmt(ms, n=2):
    return f"{ms[0]:.{n}f} ± {ms[1]:.{n}f}"


def fwd_agg(tier, h, key):
    v = [RR["tickers"][t]["forward"][tier][s][h][key] for t in T for s in range(len(SEEDS))]
    return float(np.mean(v))


def mm(d, k, n=3):
    return f"{d[k]['mean']:.{n}f} ± {d[k]['std']:.{n}f}"


